FoamFile
{
    version     2.0;
    format      ascii;
    class       volScalarField;
    object      rho.air;
}
// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //

dimensions      [1 -3 0 0 0 0 0];

internalField   uniform 1.225;

boundaryField
{
    walls
    {
        type            zeroGradient;
    }

    windows_master
    {
        type            burstCyclic;
        intactType      zeroGradient;
        value           $internalField;
    }
    windows_slave
    {
        type            burstCyclic;
        intactType      zeroGradient;
        value           $internalField;
    }

    baffles_master
    {
        type      zeroGradient;
    }
    baffles_slave
    {
        type      zeroGradient;
    }

    outlet
    {
        type            zeroGradient;
    }

    defaultFaces
    {
        type            empty;
    }
}

// ************************************************************************* //
